\begin{equation}
\label{II.(1.3)estimates}
|\nabla R(x,t)|<\eta R(x,t)^{3/2},\qquad
\left|\frac{\D R}{\D t}(x,t)\right|<\eta R(x,t)^2,
\end{equation}
where the time derivative is one-sided at surgery points and $\eta$ is the
constant from (\ref{derestimates}).
\end{definition}

